/**
 * Video provider registry (open-closed).
 *
 * Add a source: create `sources/<id>.js` (+ optional sibling folder for scrape helpers).
 * Do not edit this file, player UI, proxy, or mediaTokens for a new source.
 *
 * Default export shape:
 * {
 *   id: 'mysource',
 *   default?: true,              // at most one — unprefixed tokens / scrape default
 *   tokenPrefix: 'mysource.',    // omit for the default (unprefixed) provider
 *   referer: 'https://example/',
 *   hostMatchers: ['cdn.example'], // hostname.includes(matcher) — prefer full hosts
 *   directHlsHosts?: ['cdn.example'], // CORS * CDNs — skip proxy hop
 *   offlineQuality?: true,       // HLS quality ladder in offline download UI
 *   ensureTwCaptions?: true,     // core: AI-translate → TW WebVTT, Supabase ~1y cache
 *   videoIdHelp?: '分類 cat ID（數字）', // plain format hint; admin formats the tooltip
 *   listEpisodes(event, videoId),
 *   resolvePlayback(tokenOrPayload),
 *   decodeToken?(token),         // required when tokenPrefix is set
 * }
 *
 * resolvePlayback / episodeRecord should return only this contract (core wires the rest):
 *   s: [{ src, type? }]          // stream URLs (HLS or progressive)
 *   videoCookie?, videoReferer?  // upstream auth/headers for proxy
 *   captions?                    // [{ src, label, srclang }] — sealed by core via download-proxy
 *   thumbnails_vtt_url? | thumbnails_vtt_text?, thumbnails_jpg_url?
 *   // video_id stays server-side (sealed in episode token) — never return to client
 *   // relative VTT sprite paths are fine — core rewrites + seals them
 *
 * Restart the server after adding a source.
 * Plugins are discovered by modules/video-providers.ts → `#video-providers`.
 */
import pluginModules from '#video-providers'

const providerList = (Array.isArray(pluginModules) ? pluginModules : []).filter(
    (p) =>
        p
        && typeof p.id === 'string'
        && p.id
        && typeof p.listEpisodes === 'function'
        && typeof p.resolvePlayback === 'function',
)

const providers = Object.fromEntries(providerList.map((p) => [p.id, p]))
const defaultProvider = providerList.find((p) => p.default) || providerList[0]
if (!defaultProvider) throw new Error('No video providers registered under sources/')

export const VIDEO_SOURCES = Object.freeze(providerList.map((p) => p.id))
export const DEFAULT_VIDEO_SOURCE = defaultProvider.id

/** `{ id: formatHint }` for providers that set `videoIdHelp`. */
export const VIDEO_ID_FORMATS = Object.freeze(
    Object.fromEntries(providerList.filter((p) => p.videoIdHelp).map((p) => [p.id, p.videoIdHelp])),
)

const directHlsHosts = [
    ...new Set(providerList.flatMap((p) => (p.directHlsHosts || []).map((h) => String(h).toLowerCase()))),
]

export function isValidVideoSource(value) {
    return VIDEO_SOURCES.includes(value)
}

/** Registered id, or null — never invent a default for unknown/empty values. */
export function normalizeVideoSource(value) {
    if (!value || typeof value !== 'string') return null
    return isValidVideoSource(value) ? value : null
}

export function isDirectHlsHost(hostname) {
    if (!hostname || typeof hostname !== 'string') return false
    const host = hostname.toLowerCase()
    return directHlsHosts.some((h) => host === h || host.endsWith(`.${h}`))
}

export function getProvider(source) {
    const id = normalizeVideoSource(source)
    return id ? providers[id] : undefined
}

export function resolveVideoReferer(hostname, fallbackOrigin = '') {
    const match = providerList.find((p) => p.hostMatchers?.some((m) => hostname.includes(m)))
    if (match) return match.referer
    return fallbackOrigin ? `${fallbackOrigin.replace(/\/$/, '')}/` : ''
}

export async function listEpisodesForSource(event, source, videoId) {
    const provider = getProvider(source)
    if (!provider) throw new Error(`Unknown video source: ${source}`)
    return provider.listEpisodes(event, videoId)
}

export async function resolvePlaybackForSource(source, token) {
    const provider = getProvider(source)
    if (!provider) throw new Error(`Unknown video source: ${source}`)

    if (typeof provider.decodeToken === 'function') {
        const payload = provider.decodeToken(token)
        if (!payload) throw new Error(`Invalid ${source} token`)
        return provider.resolvePlayback(payload)
    }
    return provider.resolvePlayback(token)
}
